// Structured steps keep recipe targets separate from optional actual measurements.
let stages=[],waterMode='added';
const stageStyles=document.createElement('link');stageStyles.rel='stylesheet';stageStyles.href='stages.css';document.head.append(stageStyles);
const stepDefaults=(v={})=>({action:'注水',start:'0:00',water:0,next:'指定時間',until:'0:30',valve:'關',note:'',actualWater:'',actualTime:'',...v});
const stageRecipes={daily:[{water:40,until:'0:30'},{start:'0:30',water:80,until:'1:15'},{start:'1:15',water:80,next:'等流完',until:''}],switch:[{water:200,next:'指定時間',until:'2:00',note:'輕輕攪拌，讓咖啡粉濕潤'},{action:'開閥放水',start:'2:00',valve:'開',next:'等流完',until:''}],'46':[0,1,2,3,4].map(i=>({water:60,start:clock(i*45),until:i<4?clock((i+1)*45):'',next:i<4?'指定時間':'等流完'}))};
function clock(n){return Math.floor(n/60)+':'+String(n%60).padStart(2,'0')}
function secondsOf(t){if(!/^\d{1,3}:[0-5]\d$/.test(t))return null;const [m,s]=t.split(':').map(Number);return m*60+s}
const oldStepsLabel=form.elements.steps.closest('label');
oldStepsLabel.firstChild.textContent='補充筆記／舊版流程（保留原文）';
const stageSection=document.createElement('section');stageSection.id='stage-editor';oldStepsLabel.before(stageSection);
function renderStages(){let sum=0;const isSwitch=form.elements.method.value==='Hario Switch';stageSection.innerHTML=`<div class="stage-heading"><h3>分段沖煮流程</h3><span class="badge">${stages.filter(s=>s.action==='注水').length} 次注水 · ${stages.length} 段</span></div><p class="hint">開始與「等至」均由整杯 0:00 計時；累積目標等於磅上讀數（未歸零）。</p><div class="filters"><button type="button" data-mode="added" class="chip ${waterMode==='added'?'active':''}">輸入本段加水</button><button type="button" data-mode="total" class="chip ${waterMode==='total'?'active':''}">輸入累積目標</button></div><div id="stage-list">${stages.map((s,i)=>{sum+=s.action==='注水'?Number(s.water)||0:0;return `<article class="stage-card" data-index="${i}"><div class="stage-heading"><b>第 ${i+1} 段</b><div class="stage-tools"><button type="button" data-step="up" data-i="${i}" aria-label="第 ${i+1} 段向上移" ${i===0?'disabled':''}>↑</button><button type="button" data-step="down" data-i="${i}" aria-label="第 ${i+1} 段向下移" ${i===stages.length-1?'disabled':''}>↓</button><button type="button" data-step="copy" data-i="${i}">複製</button><button type="button" data-step="remove" data-i="${i}" aria-label="刪除第 ${i+1} 段">✕</button></div></div><div class="fields"><label>動作<select data-field="action">${['注水','等待浸泡','開閥放水','攪拌／搖晃'].map(x=>`<option ${x===s.action?'selected':''}>${x}</option>`).join('')}</select></label><label>開始時間（分:秒）<input data-field="start" value="${esc(s.start)}" placeholder="0:45" pattern="[0-9]{1,3}:[0-5][0-9]" required inputmode="text"></label></div>${s.action==='注水'?`<label>${waterMode==='added'?'本段加水':'磅上累積目標'} g<input data-field="water" type="number" min="0.1" max="3000" step="0.1" value="${waterMode==='added'?s.water:sum}" required></label><p class="stage-target" data-target="${i}">本段 +${s.water}g → 磅上加至 <strong>${sum}g</strong></p>`:''}<div class="fields"><label>下一段條件<select data-field="next">${['指定時間','等流完','手動決定'].map(x=>`<option ${x===s.next?'selected':''}>${x}</option>`).join('')}</select></label>${s.next==='指定時間'?`<label>等至總時間（分:秒）<input data-field="until" value="${esc(s.until)}" pattern="[0-9]{1,3}:[0-5][0-9]" placeholder="1:30" required></label>`:''}${isSwitch?`<label>本段閥門<select data-field="valve"><option ${s.valve==='關'?'selected':''}>關</option><option ${s.valve==='開'?'selected':''}>開</option></select></label>`:''}</div><details><summary>備註與實際紀錄（選填）</summary><label>本段備註<input data-field="note" value="${esc(s.note)}" placeholder="輕攪兩圈／中心注水"></label><div class="fields"><label>實際本段加水 g<input data-field="actualWater" type="number" min="0" step="0.1" value="${esc(s.actualWater)}" placeholder="未量度"></label><label>實際完成時間（分:秒）<input data-field="actualTime" value="${esc(s.actualTime)}" pattern="[0-9]{1,3}:[0-5][0-9]" placeholder="未量度"></label></div></details></article>`}).join('')}</div><button type="button" class="add-stage" data-step="add">＋ 加一段</button><div id="stage-summary" role="status"></div>`;updateSummary()}
function updateSummary(){const total=stages.reduce((n,s)=>n+(s.action==='注水'?+s.water||0:0),0);const target=+form.elements.water.value;const mismatch=stages.length&&Math.abs(total-target)>0.05;$('#stage-summary').className='stage-summary'+(mismatch?' mismatch':'');$('#stage-summary').innerHTML=`<strong>注水合計 ${Math.round(total*10)/10}g</strong> · ${stages.filter(s=>s.action==='注水').length} 次注水${mismatch?`<br>與上方總注水 ${target}g 不同。<button type="button" class="text-link" data-step="sync">將總注水設為 ${Math.round(total*10)/10}g</button>`:' · 與總注水一致'}`;let sum=0;stages.forEach((s,i)=>{if(s.action==='注水'){sum+=+s.water||0;const el=stageSection.querySelector(`[data-target="${i}"]`);if(el)el.innerHTML=`本段 +${s.water}g → 磅上加至 <strong>${Math.round(sum*10)/10}g</strong>`}})}
stageSection.addEventListener('input',e=>{const el=e.target,k=el.dataset.field;if(!k)return;const i=+el.closest('[data-index]').dataset.index;el.setCustomValidity('');let value=el.value;if(k==='water'){value=Number(value);if(waterMode==='total'){const previous=stages.slice(0,i).reduce((n,s)=>n+(s.action==='注水'?+s.water||0:0),0);value-=previous;if(value<=0)el.setCustomValidity('累積目標必須大於上一段累積水量')}}stages[i][k]=value;updateSummary()});
stageSection.addEventListener('change',e=>{if(['action','next','valve'].includes(e.target.dataset.field)||(e.target.dataset.field==='water'&&waterMode==='total'&&e.target.validity.valid))renderStages()});
stageSection.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.mode){waterMode=b.dataset.mode;renderStages();return}const i=+b.dataset.i;switch(b.dataset.step){case'add':{const last=stages.at(-1);stages.push(stepDefaults({start:last?(last.until||last.start):'0:00',water:0}));break}case'copy':stages.splice(i+1,0,{...stages[i],actualTime:'',actualWater:''});break;case'remove':stages.splice(i,1);break;case'up':[stages[i-1],stages[i]]=[stages[i],stages[i-1]];break;case'down':[stages[i+1],stages[i]]=[stages[i],stages[i+1]];break;case'sync':form.elements.water.value=Math.round(stages.reduce((n,s)=>n+(s.action==='注水'?+s.water||0:0),0)*10)/10;ratio();break;default:return}renderStages()});
const originalOpen=openBrew;openBrew=function(r){originalOpen(r);stages=Array.isArray(r?.stages)?r.stages.map(s=>stepDefaults({...s})):r?.id&&stageRecipes[r.id]?stageRecipes[r.id].map(s=>stepDefaults(s)):r?[]:stageRecipes.switch.map(s=>stepDefaults(s));waterMode='added';renderStages()};
const originalPreset=$('#preset').onchange;$('#preset').onchange=e=>{originalPreset(e);if(stageRecipes[e.target.value]){stages=stageRecipes[e.target.value].map(s=>stepDefaults(s));form.elements.steps.value='';renderStages()}};
form.elements.method.addEventListener('change',renderStages);form.elements.water.addEventListener('input',()=>{if($('#stage-summary'))updateSummary()});
const originalPersist=persist;persist=function(next){return originalPersist(next.map(r=>r.id===editing||(!editing&&r===next[0])?{...r,stages:stages.map(s=>({...s}))}:r))};
const originalSubmit=form.onsubmit;form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;let last=-1;for(const s of stages){const t=secondsOf(s.start);if(t===null||t<last){toast('請按先後次序設定每段開始時間');return}if(s.next==='指定時間'&&(secondsOf(s.until)===null||secondsOf(s.until)<t)){toast('「等至」時間不可早於本段開始時間');return}if(s.action==='注水'&&(!Number.isFinite(+s.water)||+s.water<=0)){toast('每段注水需大於 0g');return}last=t}const total=stages.reduce((n,s)=>n+(s.action==='注水'?+s.water:0),0);if(stages.length&&Math.abs(total-+form.elements.water.value)>.05){toast('請先對齊分段水量與總注水量');$('#stage-summary').scrollIntoView({block:'center',behavior:'smooth'});return}originalSubmit(e)};
